 */
export interface RetryOptions {
  /** Maximum number of attempts (including the first). Default: 5 */
  maxAttempts?: number;
  /** Base delay in milliseconds. Default: 100 */
  baseDelay?: number;
  /** Maximum delay in milliseconds. Default: 10000 */
  maxDelay?: number;
  /** Backoff multiplier. Default: 2 */
  factor?: number;
  /**
   * Maximum random jitter in milliseconds to add to each delay.
   * Helps avoid thundering herd problems. Default: 250
   */
  jitter?: number;
  /**
   * Predicate to determine if an error is retryable.
   * Return false to stop retrying and propagate the error.
   */
  isRetryable?: (error: unknown) => boolean;
  /**
   * Optional callback invoked before each retry with the attempt info.
   */
  onRetry?: (info: RetryInfo) => void;
  /**
   * Optional AbortSignal to cancel the retry operation.
   */
  signal?: AbortSignal;
}

/**
 * Information passed to the onRetry callback.
 */
export interface RetryInfo {
  /** The attempt number that just failed (1-based). */
  attempt: number;
  /** The error that caused the retry. */
  error: unknown;
  /** The delay in milliseconds before the next attempt. */
  delay: number;
}

